import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms'; // 1. استيراد FormsModule

@Component({
  selector: 'app-login',
  standalone: true, // لو المشروع بيستخدم Standalone Components
  imports: [CommonModule, FormsModule], // 2. إضافتها هنا عشان الـ ngForm يشتغل
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {

  // 3. تعريف دالة onSubmit عشان تبطل تطلع إيرور
  onSubmit() {
    console.log('Form Submitted!');
  }

}
